def hull_poly(points): return hull(points)
def inpoly_incl(x,y,poly):
 # use strict interior or exactly on edge
 for i in range(len(poly)):
  x1,y1=poly[i];x2,y2=poly[(i+1)%len(poly)]
  if abs((x-x1)*(y2-y1)-(y-y1)*(x2-x1))<1e-8 and min(x1,x2)<=x<=max(x1,x2) and min(y1,y2)<=y<=max(y1,y2):return True
 return inside(x,y,poly)
def pairfan(segA,segB):
 (ra,ca),(ea,xa)=segA; (rb,cb),(eb,xb)=segB
 # fan down from start A, fan up from end B
 cells=set()
 for r in range(max(ra,0),min(eb,15)+1):
  alo=ca-(r-ra); ahi=ca+(r-ra)
  blo=xb-(eb-r); bhi=xb+(eb-r)
  lo=max(alo,blo);hi=min(ahi,bhi)
  for c in range(max(0,lo),min(15,hi)+1):cells.add((c,r))
 return cells
