 return { (c,r) for r in range(rs,re+1) for c in range(max(0,cs-(r-rs)),min(15,cs+(r-rs))+1)}
def fan_end(seg):
 (rs,cs),(re,ce)=seg
 return { (c,r) for r in range(rs,re+1) for c in range(max(0,ce-(re-r)),min(15,ce+(re-r))+1)}
def pair_allfans(a,b,poly):
